# Generated by the jhooq.com VPC Subnet Planner - https://jhooq.com/tools/vpc-subnet-planner/
PROJECT=my-project
REGION=europe-west3
NET=jhooq-vpc

# A Google Cloud VPC has no CIDR of its own; 10.30.0.0/16 is your address plan.
gcloud compute networks create $NET --project=$PROJECT --subnet-mode=custom

gcloud compute networks subnets create private --project=$PROJECT --network=$NET --region=$REGION \
  --range=10.30.0.0/20 --enable-private-ip-google-access

gcloud compute networks subnets create public --project=$PROJECT --network=$NET --region=$REGION \
  --range=10.30.16.0/24

gcloud compute networks subnets create database --project=$PROJECT --network=$NET --region=$REGION \
  --range=10.30.17.0/24 --enable-private-ip-google-access

# Terraform (google provider)
# resource "google_compute_subnetwork" "...": ip_cidr_range = "<cidr>", region = var.region, network = google_compute_network.net.id
